sources.BulletinPanel.ets:
@Component
export struct BulletinPanel {
  body: string = ''
  cleanBody(): string {
    return this.body.replace('<p>', '').replace('</p>', '')
  }
  build() {
    Column() { Text(this.cleanBody()) }
  }
}

